// Logo de Huasca Retreats, incrustado como base64 para usarse en los
// correos (adjunto inline vía cid). Se hace así -en vez de referenciar
// /logo.png por URL- porque:
//   1. Gmail y varios clientes de correo bloquean imágenes remotas por
//      defecto hasta que el usuario le da clic a "mostrar imágenes".
//   2. El sitio todavía no está en línea en huascaretreats.com, así que
//      una URL remota estaría rota de cualquier forma.
// Adjuntar el archivo con un Content-ID (cid) hace que el logo se vea
// siempre, sin depender de que el dominio esté publicado.
// Versión reducida (160x160) para que el correo no pese de más.
export const LOGO_CID = 'huasca-logo'
export const LOGO_PNG_BASE64 =
  ''
